-- Inicialización de la tabla de ejercicios con datos reales
CREATE TABLE IF NOT EXISTS ejercicios (
  id SERIAL PRIMARY KEY,
  nombre VARCHAR(150) NOT NULL,
  grupo_muscular VARCHAR(30) NOT NULL,
  equipo VARCHAR(50) NOT NULL DEFAULT 'ninguno',
  dificultad VARCHAR(20) NOT NULL DEFAULT 'intermedio',
  calorias_por_minuto DECIMAL(5,2) DEFAULT 6.0,
  gif_url VARCHAR(255) NOT NULL,
  instrucciones TEXT,
  series_recomendadas INT DEFAULT 3,
  repeticiones_recomendadas VARCHAR(20) DEFAULT '10-12',
  activo BOOLEAN DEFAULT TRUE,
  CONSTRAINT chk_grupo_muscular CHECK (grupo_muscular IN ('pecho','espalda','piernas','hombros','brazos','core'))
);

